# -*- coding: utf-8 -*-
"""Every calculator page: fields, words and questions. English first, Hindi second."""

def N(name, en, hi, default, pre="₹", suf=None, mn=0, mx=None, step="any", money=None, help=None):
    return dict(t="num", name=name, en=en, hi=hi, d=default, pre=pre, suf=suf, mn=mn, mx=mx, step=step,
                money=(pre == "₹") if money is None else money, help=help)
def P(name, en, hi, default, mx=100, step="0.01", help=None):
    return N(name, en, hi, default, pre=None, suf="%", mx=mx, step=step, money=False, help=help)
def S(name, en, hi, opts, default):
    return dict(t="seg", name=name, en=en, hi=hi, opts=opts, d=default)
def SEL(name, en, hi, opts, default):
    return dict(t="sel", name=name, en=en, hi=hi, opts=opts, d=default)
def CHK(name, en, hi, default=True):
    return dict(t="chk", name=name, en=en, hi=hi, d=default)
def D(name, en, hi, default=""):
    return dict(t="date", name=name, en=en, hi=hi, d=default)

